package com.ivonix.pulse.ontology.academy;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.client.RestTemplate; import java.util.*;
@Service public class CertificateRenderClient{private final RestTemplate rest;private final String url,secret;public CertificateRenderClient(RestTemplate r,@Value("${PULSE_CERT_RENDERER_URL:http://pulse-cert-renderer:8095}")String u,@Value("${PULSE_CERT_RENDERER_SECRET:}")String s){rest=r;url=u.replaceAll("/$","");secret=s;if(secret.isBlank())throw new IllegalStateException("PULSE_CERT_RENDERER_SECRET is required");}public void render(UUID id,String title,String user,String number,String signature,String issued,String path){HttpHeaders h=new HttpHeaders();h.setContentType(MediaType.APPLICATION_JSON);h.setBearerAuth(secret);Map<String,Object> body=Map.of("certificateId",id,"courseTitle",title,"userName",user,"certificateNumber",number,"signature",signature,"issuedAt",issued,"storagePath",path);ResponseEntity<Void> r=rest.exchange(url+"/render",HttpMethod.POST,new HttpEntity<>(body,h),Void.class);if(!r.getStatusCode().is2xxSuccessful())throw new IllegalStateException("Certificate PDF render failed");}}
